input.function:
() => {
  const all = document.querySelectorAll('[class*="prose"], main, article');
  for (let el of all) {
    const t = el.innerText;
    if (t && t.length > 2000) return t.substring(4500, 7500);
  }
  return document.body.innerText.substring(4500, 7500);
}

